mapper.select:
SELECT id, escalation_id, experiment_id, approval_type, draft_version, app_id, owner, experiment_name,
       approval_submitted_at, approval_elapsed_hours, approval_sla_hours, approval_sla_status,
       escalation_owners, escalation_reason, notification_channel, notification_payload_json,
       notification_status, notification_attempt_count, notification_last_attempt_at,
       notification_next_attempt_at, notification_delivered_at, notification_last_error,
       escalation_status, acknowledged_by, acknowledged_comment, acknowledged_at,
       resolved_by, resolved_reason, resolved_at, created_at, updated_at
FROM pisces_experiment_approval_escalation
WHERE experiment_id = #{experimentId}
  AND approval_type = #{approvalType}
  AND draft_version = #{draftVersion}
  AND approval_submitted_at = #{approvalSubmittedAt}

